import { useParams } from 'react-router-dom';
import { LoadingSpinner } from '@/components/Loading/LoadingSpinner';
import { useEffect, useState } from 'react';
import { apiGet } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import UnderlineHeading from '@/components/heading/UnderlineHeading';
// import DocumentUpload from '../components/addDepartment/DocumentUpload';
import { Department } from '@/types/department.types';
import AddDepartmentForm from '../../forms/addDepartment/AddEmployeeForm';

export default function EditDepartmentPage() {
    const params = useParams();
    const { id } = params;
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [department, setDepartment] = useState<Department | null>(null);

    useEffect(() => {
        const fetchDepartment = async () => {
            try {
                const response = await apiGet({
                    endpoint: endpoints.departments.show + id,
                });
                const row = response.data?.data;
                setDepartment(row ?? null);
            } catch {
                setError('تعذر تحميل بيانات القسم');
            } finally {
                setLoading(false);
            }
        };
        if (id) {
            fetchDepartment();
        } else {
            setError('Invalid Department ID');
            setLoading(false);
        }
    }, [id]);

    if (loading) {
        return <LoadingSpinner />;
    }

    if (error) {
        return (
            <div className="mt-6 mb-[102px] text-center py-20">
                <h2 className="text-xl text-red-500">{error}</h2>
            </div>
        );
    }

    if (!department) {
        return (
            <div className="mt-6 mb-[102px] text-center py-20">
                <h2 className="text-xl">لم يُعثر على القسم</h2>
            </div>
        );
    }
    return (
        <div className="w-full mt-6">
            <div className="flex flex-row justify-between mb-6">
                <UnderlineHeading className="h-fit" text="تعديل بيانات القسم" />
                {/* <DocumentUpload /> */}
            </div>
            <AddDepartmentForm department={department} />
        </div>
    );
}
